(()=>{const b=window.DriveQuizBank;if(!b)throw Error("Missing DriveQuizBank");b.questions.push(...[{"id":"rodrive-b-1001","batch":"21","category":"Categoria B","question":"Oprirea voluntară a vehiculelor este interzisă:","answers":["Pe platforma căii ferate sau de tramvai, dacă prin aceasta este stânjenită circulația vehiculelor pe șine","La mai puțin de 50 m de trecerile pentru pietoni","La o distanță mai mică de 150 m de trecerea la nivel cu calea ferată"],"correctIndices":[0],"correct":0,"explanation":"Oprirea voluntară a vehiculelor este interzisă pe platforma căii ferate, fie ea industrială sau curentă, precum și pe platforma căii de tramvai ori la mai puțin de 50 de metri de toate acestea, dacă circulația vehiculelor pe șine ar putea fi stânjenită sau împiedicată. Oprirea voluntară este permisă la mai puțin de 50 de metri de trecerile pentru pietoni, oprirea fiind interzisă pe trecerile pentru pietoni sau la mai puțin de 25 de metri înainte și după acestea. Oprirea este permisă la o distanță mai mică de 150 de metri de trecerea la nivel cu calea ferată, oprirea fiind interzisă pe trecerea la nivel cu calea ferată sau la o distanță mai mică de 50 de metri înainte și după aceasta.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1001.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1001.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1001; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1000 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/oprirea-voluntara-a-vehiculelor-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1000","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1002","batch":"21","category":"Categoria B","question":"În timp ce conduceți un autoturism, aveți voie să efectuati manevra de depășire a unui autobuz oprit în stație pentru urcarea și coborârea călătorilor?","answers":["Da","Da, numai dacă lățimea drumului public este mai mare de 6 m","Nu, în acest caz depășirea este interzisă"],"correctIndices":[0],"correct":0,"explanation":"În situația în care întâlniți un autobuz oprit într-o stație pentru urcarea sau coborârea pietonilor vă este permis să efectuați manevra de depășire a acestuia, respectând toate regulile privind manevra de depășire. Din punct de vedere al conduitei preventive, trebuie să circulați cu atenție sporită deoarece unii călători pot traversa strada prin fața autobuzului fără să se asigure.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1002.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1002.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1002; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1001 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-timp-ce-conduceti-un-autoturism-aveti-voie-sa-efectuati-manevra-de-depasire-a-unui-autobuz-oprit-in-statie-pentru-urcarea-si-coborarea-ca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1001","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1003","batch":"21","category":"Categoria B","question":"Cum este corect să procedați în situația prezentată?","answers":["Sunteți obligat să așteptați","Nu aveți nicio obligație","Semnalizați autobuzul galben că poate circula"],"correctIndices":[1],"correct":1,"explanation":"Intersecția în care doriți să pătrundeți este o intersecție nedirijată, intersecție în care se va aplica regula priorității de dreapta, în această situație aveți prioritate de trecere față de autobuz, acesta fiind obligat să vă acorde prioritate deoarece dumneavoastră circulați din partea dreaptă a acestuia. Prin urmare, în această situație nu aveți obligația de a acorda prioritate și vă puteți continua deplasarea pe direcția dorită.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1003.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1003.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1003; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată o intersecție nedirijată, din perspectiva unui șofer, ce observă și indicatorul 'Direcție obligatorie la dreapta'. Șoferul este nevoit să vireze la dreapta. Din partea stânga, vine un autobuz care intenționează să meargă înainte.","needsImageReview":true,"source":"RoDrive · ID 1002 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-este-corect-sa-procedati-in-situatia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1002","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1029.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1004","batch":"21","category":"Categoria B","question":"Puteți circula cu vehiculul într-o zonă pietonală dacă:","answers":["Prestați servicii comerciale","Aveți sistemul de iluminare în stare de funcționare","Locuiţi în acea zonă"],"correctIndices":[2],"correct":2,"explanation":"În zonele pietonale, semnalizate ca atare, conducătorul de vehicul poate intra numai dacă locuiește în acea zonă sau dacă prestează servicii publice „din poartă în poartă” și nu are altă posibilitate de acces.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1004.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1004.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1004; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1003 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/puteti-circula-cu-vehiculul-intr-o-zona-pietonala-daca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1003","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1005","batch":"21","category":"Categoria B","question":"Puteți executa depășirea în această situație?","answers":["Da, legea nu interzice","Nu, deoarece drumul se îngustează","Nu, deoarece urmează un drum în lucru"],"correctIndices":[0],"correct":0,"explanation":"În situația dată întâlniți indicatorul „Îngustare temporară” împreună cu un panou adițional pe care este înscris „400 m”. Acest indicator împreună cu panoul adițional vă avertizează că peste 400 de metri veți întâlni o îngustare temporară a drumului pe partea stângă. Pentru că îngustarea temporară a drumului începe la 400 de metri de acest indicator, puteți efectua depășirea, distanța până la îngustarea drumului fiind suficientă pentru efectuarea manevrei de depășire în condiții de siguranță.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1005.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1005.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1005; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul galben cu săgeata neagră înainte și o altă linie frântă care se oprește în dreptul săgeții și inscripția '400 m' semnalizează îngustarea temporară a drumului numărului de benzi în 400 de metri. În fața sa, pe banda din dreapta sa, se află un camion. Șoferul inteționează să rămână pe banda care va fi îngustată, pentru a depăși camionul, ajungând astfel pe banda normală.","needsImageReview":true,"source":"RoDrive · ID 1004 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/puteti-executa-depasirea-in-aceasta-situatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1004","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1031.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1006","batch":"21","category":"Categoria B","question":"Indicatorul semnifică:","answers":["Reducerea numărului benzilor de circulație","Îngustare temporară a drumului","Terminarea benzii de circulație din stânga părții carosabile"],"correctIndices":[1],"correct":1,"explanation":"În situația dată întâlniți indicatorul \"Îngustare temporară\", acest indicator se instalează pe sectoarele de drum unde se efectuează lucrări la partea carosabilă și vă avertizează că veți întâlni o îngustare temporară a drumului pe partea stângă. Vehiculele care circulă pe banda numărul 3 (banda care se termină) și intenționează să treacă pe banda numărul 2, vor trebui să acorde prioritate celor de pe banda numărul 2.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1006.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1006.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1006; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul dreptunghiular galben cu două săgeți orientate înainte, cea din stânga având o linie frântă ce se oprește în dreptul săgeții.","needsImageReview":true,"source":"RoDrive · ID 1005 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1005","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1032.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1007","batch":"21","category":"Categoria B","question":"La trecerile pentru pietoni nesemaforizate, semnalizate corespunzător, când drumul are cel mult o bandă pe sens, iar pietonii aflați pe trotuar, în imediata apropiere a părții carosabile, intenționează să se angajeze în traversare, trebuie:","answers":["Să circulați cu o viteză care să nu depășească 30 km/h în localități sau 50 km/h în afara acestora","Să reduceți brusc viteza și să acordați prioritate de trecere pietonilor care au acest drept","Nu aveți nicio obligație legală și nici vreo răspundere în cazul unui eventual accident"],"correctIndices":[0],"correct":0,"explanation":"La trecerile pentru pietoninesemaforizate,semnalizate prin indicatoare și marcaje, când drumul public areo singură bandă de circulație pentru fiecare sens, se procedează după cum urmează: Trebuie reținut că legislația rutieră impune această obligație de a circula cu o viteza care să nu depășească 30 km/h în localități sau 50 km/h în afara localităților dacă trecerea pentru pietoni care estenesemaforizată, semnalizată prin indicatoare și marcaje,se afla pe un drum cu o singură bandă de circulație pe sens, iar pietonii aflați pe trotuar, în imediată apropiere a părții carosabile, intenționează să se angajeze în traversare.În cazul în care drumul are două sau mai multe benzi de circulație pe sens, această obligație privind viteza de deplasarenu se mai aplică, indiferent dacă se află pietoni în imediata apropiere a trecerii pentru pietoni care intenționează să se angajeze în traversare, însă rămâne obligația de a acorda prioritate pietonilor, atunci când aceștia se află pe sensul dumneavoastră de mers. Mai multe informații despre obligațiile pe care le are conducătorul de vehicul la trecerea pentru pietoni, în funcție de tipul acesteia și de numărul de benzi pe sens, găsiți în lecția Audio-Video „Capitolul 4 partea 2 - Trecerea pentru pietoni și obligațiile pietonilor” din pasul 1 de pe Școala Rutieră. Viteza de deplasare nu se va reduceBRUSC. Dacă așteptați până în ultimul moment și frânați brusc este posibil să nu puteți opri într-un spațiu util. Viteza de deplasare se va reduce brusc în situația în care acest lucru este necesar pentru evitarea unui pericol imediat. Având în ","imageUrl":"/nivel-1/quiz-images/rodrive-all/1007.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1007.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1007; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1006 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-trecerile-pentru-pietoni-nesemaforizate-semnalizate-corespunzator-cand-drumul-are-cel-mult-o-banda-pe-sens-iar-pietonii-aflati-pe-trotuar","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1006","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1008","batch":"21","category":"Categoria B","question":"În această situație, cum puteți staționa regulamentar?","answers":["Cu toate luminile stinse","Numai cu luminile de poziție","Numai cu luminile de avarie"],"correctIndices":[0],"correct":0,"explanation":"Puteți staționa autovehiculul cu toate luminile stinse atunci când drumul este iluminat astfel încât acesta să fie vizibil de la o distanță de cel puțin 50 de metri. Prin urmare, în situația dată, drumul fiind iluminat și vehiculul fiind vizibil de la cel puțin 50 de metri, puteți staționa cu toate luminile stinse.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1008.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1008.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1008; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o situație de trafic nocturn pe un drum urban bine iluminat.","needsImageReview":true,"source":"RoDrive · ID 1007 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-aceasta-situatie-cum-puteti-stationa-regulamentar","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1007","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1034.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1009","batch":"21","category":"Categoria B","question":"Poate staționa noaptea, pe un drum public, remorca unui autoturism?","answers":["Nu","Da, dacă drumul este iluminat","Da, dacă aceasta este semnalizată cu triunghiuri reflectorizante"],"correctIndices":[0],"correct":0,"explanation":"Se interzice staționarea pe partea carosabilă a drumurilor publice, în timpul nopții, a tractoarelor, a remorcilor, a mopedelor, a bicicletelor, a mașinilor și utilajelor autopropulsate utilizate în lucrări de construcții, agricole sau forestiere, a vehiculelor cu tracțiune animală ori a celor trase sau împinse cu mâna.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1009.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1009.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1009; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1008 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/poate-stationa-noaptea-pe-un-drum-public-remorca-unui-autoturism","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1008","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1010","batch":"21","category":"Categoria B","question":"Panoul de sub indicator permite:","answers":["Staționarea mijloacelor de transport public de persoane în intervalul menționat","Staționarea în timpul orelor menționate","Staționarea în afara intervalului orar menționat"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul pe care l-ați întâlnit se numește “Staționarea interzisă”, la întalnirea acestui indicator staționarea vehiculelor este interzisă, sub acest indicator se găsește instalat un panou adițional care precizează intervalul orar în care se va respecta interzicerea impusă de indicator. În situația dată se interzice staționarea vehiculelor în intervalul orar 7:00 – 10:00, în afara acestui interval orar nu se interzice staționarea. Considerând că situația din imagine se petrece la ora 11:00, staționarea vehiculelor este permisă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1010.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1010.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1010; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul circular albastru cu margini roșii și o linie roșie diagonală este însoțit de un panou adițional care precizează intervalul orar (7:00 - 10:00h).","needsImageReview":true,"source":"RoDrive · ID 1009 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/panoul-de-sub-indicator-permite","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1009","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1035.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1011","batch":"21","category":"Categoria B","question":"Prioritatea de trecere se acordă în următoarea situație:","answers":["La întâlnirea indicatorului „prioritate pentru circulația din sens invers\"","La întâlnirea indicatorului „intersecție cu un drum fără prioritate\"","La întâlnirea indicatorului „sfârșitul drumului cu prioritate\""],"correctIndices":[0],"correct":0,"explanation":"La întâlnirea indicatorului “Prioritate pentru circulația din sens invers” aveți obligația să acordați prioritate de trecere tuturor vehiculelor care circulă din sens opus. Indicatorul “Intersecție cu un drum fără prioritate”, vă avertizează că vă apropiați de o intersecție cu un drum fără prioritate, intersecție în care veți avea prioritate de trecere. Indicatorul “Sfârșitul drumului cu prioritate”, vă informează că pe drumul pe care circulați prioritatea a luat sfârșit iar în următoarea intersecție toate drumurile sunt de aceeași categorieși va trebui să respectați regulile aplicabile în acea intersecție. Prin urmare, prioritate de trecere se va acorda la întâlnirea indicatorului “Prioritate pentru circulația din sens invers”.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1011.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1011.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1011; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1010 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/prioritatea-de-trecere-se-acorda-in-urmatoarea-situatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1010","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1012","batch":"21","category":"Categoria B","question":"Sustragerea de la recoltarea probelor biologice, în vederea stabilirii alcoolemiei, constituie:","answers":["Infracțiune, și atrage anularea permisului de conducere","Contravenție, și se pedepsește cu închisoare","Contravenție, și atrage reținerea permisului de conducere"],"correctIndices":[0],"correct":0,"explanation":"Refuzul sau sustragerea conducătorului unui vehicul, pentru care legea impune deținerea permisului de conducere, de la prelevarea de mostre biologice necesare pentru determinarea alcoolemiei sau prezenței substanțelor psihoactive constituie infracțiune și se pedepsește cuînchisoarea de la unu la 5 aniși cu aplicarea măsurii de reținere a permisului de conducereîn vederea anulării acestuia.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1012.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1012.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1012; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1011 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/sustragerea-de-la-recoltarea-probelor-biologice-in-vederea-stabilirii-alcoolemiei-constituie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1011","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1013","batch":"21","category":"Categoria B","question":"Pentru a conduce ecologic un autovehicul, se recomandă:","answers":["Folosirea motorului la relanti, în cazul în care staționați mai mult timp în același loc","Menținerea unei viteze constante, de preferință medie","Oprirea motorului în timp ce coborâți o pantă, pentru a economisi carburant"],"correctIndices":[1],"correct":1,"explanation":"Nu se recomandă, din punct de vedere ecologic, folosirea motorului la ralanti, în cazul în care staționați mai mult timp în același loc. Pentru a conduce ecologic un autovehicul se recomandă menținerea unei viteze constante, de preferință medie. Oprirea motorului în timpul mersului nu este permisă. Oprirea motorului se recomandă, în scopul reducerii consumului de combustibil, în cazul unei opriri lungi la o trecere la nivel cu calea ferată sau la culoarea roșie a unui semafor care de regulă durează foarte mult.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1013.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1013.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1013; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1012 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pentru-a-conduce-ecologic-un-autovehicul-se-recomanda","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1012","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1014","batch":"21","category":"Categoria B","question":"Care dintre vehicule au prioritate de trecere prin intersecția prezentată?","answers":["Autocamionul și autoturismul","Motocicleta și tramvaiul","Motocicleta și autocamionul"],"correctIndices":[2],"correct":2,"explanation":"Deșis eamănăcu o intersecție în care circulația se desfășoară în sens giratoriu, NU ESTE UN SENS GIRATORIU. În această intersecție circulația este dirijată cu indicatoare de reglementare de prioritate.Deci nu este un sens giratoriu. Sub fiecare indicator se găsește instalat câte un panou adițional care ne indică direcția drumului cu prioritate. Autoturismul și tramvaiul vin de pe drumuri fără prioritate, întâlnind indicatorul “Cedează trecerea” și au obligația de a acorda prioritate de trecere motocicletei și autocamionului. Motocicleta și autocamionul au prioritate de trecere, deoarece vin de pe drumuri cu prioritate, ambele întâlnind indicatorul “Drum cu prioritate”. Prin urmare, în această intersecție au prioritate de trecere motocicleta și autocamionul, aceștia vor trece primii prin această intersecție.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1014.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1014.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1014; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție dirijată, cu configurație de sens giratoriu, semnalizată cu indicatoare de prioritate, inclusiv 'Cedează trecerea' și 'Drum cu prioritate'. Tramvaiul pătrunde în intersecție, deși nu este pe drum prioritar. Autoturismul vrea să vireze la stânga și vine din dreapta, dar nu se află pe drum prioritar. Autocamionul și motocicleta se află pe drum prioritar și vor să îl urmeze.","needsImageReview":true,"source":"RoDrive · ID 1013 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-vehicule-au-prioritate-de-trecere-prin-intersectia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1013","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1041.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1015","batch":"21","category":"Categoria B","question":"Întoarcerea unui vehicul este interzisă:","answers":["La o distanță mai mică de 100 m de stațiile de autobuz, troleibuz sau tramvai","Pe drumurile pe care o bandă de circulație este ocupată de linia de tramvai","La mai puțin de 50 m de trecerea la nivel cu o cale ferată curentă"],"correctIndices":[2],"correct":2,"explanation":"Întoarcerea vehiculeloreste permisăla o distanță mai mică de 100 de metri de stațiile mijloacelor de transport public. Întoarcerea vehiculelor fiind interzisă în stațiile mijloacelor de transport public de persoane și la mai puțin de 25 de metri înainte și după acestea, deoarece oprirea vehiculelor este interzisă în aceste locuri. Întoarcerea vehiculeloreste permisăpe drumurile pe care o bandă de circulație este ocupată de linia de tramvai. Întoarcerea vehiculelor fiind interzisă pe platforma căii de tramvai ori la mai puțin de 50 de metri de aceasta,dacă circulația vehiculelor pe sine ar putea fi stânjenită sau împiedicată, deoarece oprirea vehiculelor este interzisă în aceste locuri. Întoarcerea vehiculeloreste interzisăîn locurile în care oprirea vehiculelor este interzisă, iar oprirea vehiculelor este interzisă pe trecerile la nivel cu calea ferată curentă și la o distanță mai mică de 50 de metri înainte și după acestea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1015.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1015.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1015; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1014 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intoarcerea-unui-vehicul-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1014","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1016","batch":"21","category":"Categoria B","question":"În situația dată, sunteți obligat:","answers":["Să virați la dreapta până la indicator","Să virați la dreapta, deoarece urmează un sector de drum îngustat","Să ocoliți scuarul pe care este instalat indicatorul"],"correctIndices":[0],"correct":0,"explanation":"În situația dată întâlniți indicatorul “La dreapta”, acest indicator vă obligă să circulați în direcția indicată de săgeată și să reduceți viteza de deplasare, în situația dată, veți reduce viteza de deplasare și veți vira obligatoriu către dreapta.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1016.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1016.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1016; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Un drum din perspectiva unui șofer ce întalneste indicatorul circular albastru cu săgeata orientată spre dreapta ce semnifică 'Direcție obligatorie la dreapta'.","needsImageReview":true,"source":"RoDrive · ID 1015 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-situatia-data-sunteti-obligat","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1015","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1043.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1017","batch":"21","category":"Categoria B","question":"Cum procedați când circulați pe un drum public și întâlniți indicatorul „Prioritate față de circulația din sens invers“?","answers":["Opriți și acordați prioritate de trecere vehiculelor care se apropie din sens opus","Vă continuați deplasarea, pentru că aveți prioritate de trecere","Opriți și acordați prioritate numai vehiculelor cu gabarit depășit, care se apropie din sens opus"],"correctIndices":[1],"correct":1,"explanation":"La întâlnirea indicatorului „Prioritate față de circulația din sens invers”, vă puteți continua deplasarea deoarece aveți prioritate de trecere față de toate vehiculele care circulă din sens opus. Acestea, care circulă din sens opus, întâlnesc indicatorul „Prioritate pentru circulația din sens invers” și trebuie să vă acorde prioritate de trecere. Acest indicator rutier se întâlnește pe sectoarele de drum îngustat, unde nu au loc să circule două vehicule, unul pe lângă celălalt.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1017.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1017.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1017; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1016 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-cand-circulati-pe-un-drum-public-si-intalniti-indicatorul-prioritate-fata-de-circulatia-din-sens-invers","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1016","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1018","batch":"21","category":"Categoria B","question":"Este permisă parcarea autoturismelor pe trotuar, dacă se asigură spațiu de cel puțin 1 m pentru circulația pietonilor?","answers":["Nu, întrucât trotuarul este rezervat în exclusivitate deplasării pietonilor","Da, dar numai în acele zone unde există reglementări în acest sens","Da, când vehiculul trebuie scos de pe partea carosabilă pentru a nu stânjeni autovehiculele aflate în mișcare"],"correctIndices":[1],"correct":1,"explanation":"Se consideră parcare staționarea vehiculelor în spații special amenajate sau stabilite și semnalizate corespunzător. Vă este permisă parcarea autoturismului pe trotuar atunci când în acea zonă există reglementări în acest sens, ca de exemplu situatia în care se întâlnește indicatorul „Parcare” ce are inscripționat pe acesta un autoturism ce are toate roțile pe trotuar, situație în care se permite parcarea vehiculelor în respectiva zonă iar vehiculul va fi așezat cu toate roțile pe trotuar, având obligația de a respecta condiția ca lățimea minimă a trotuarului rămas la dispoziția pietonilor să fie de cel puțin un metru.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1018.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1018.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1018; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1017 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-permisa-parcarea-autoturismelor-pe-trotuar-daca-se-asigura-spatiu-de-cel-putin-1-m-pentru-circulatia-pietonilor","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1017","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1019","batch":"21","category":"Categoria B","question":"Ce trebuie să facă conducătorul auto în situația prezentată?","answers":["Să reducă viteza","Să oprească","Să nu depășească motocicleta de poliție"],"correctIndices":[0],"correct":0,"explanation":"Polițistul rutier execută un semnal prin balansarea pe verticală a brațului, acest semnal semnifică reducerea vitezei de deplasare, indiferent dacă polițistul efectuează acest semnal dint-un autovehicul al poliției sau nu. În această situație conducătorul autoturismului este obligat să reducă viteza de deplasare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1019.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1019.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1019; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Polițistul din motocicletă circulă înainte, iar autoturismul verde se află în spatele lui. Polițistul din imagine își balansează brațul cu palma în jos, indicând reducerea vitezei pentru vehiculele care se află în spatele lui.","needsImageReview":true,"source":"RoDrive · ID 1018 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-trebuie-sa-faca-conducatorul-auto-in-situatia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1018","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1046.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1020","batch":"21","category":"Categoria B","question":"Care dintre cele trei vehicule nu au prioritate de trecere?","answers":["Autoturismul și autobuzul","Autobuzul și autocamionul","Autocamionul și autoturismul"],"correctIndices":[2],"correct":2,"explanation":"Intersecția din imagine este dirijată cu indicatoare de reglementare de prioritate, sub fiecare indicator se găsește câte un panou adițional care ne indică direcția drumului cu prioritate. Autocamionul vine de pe drumul fără prioritate, întâlnind indicatorul “Cedează trecerea” și trebuie să le acorde prioritate celorlalte autovehicule. Între autobuz și autoturism s-a creat o situație de egalitate, deoarece ambele vin de pe drumuri cu prioritate, întâlnind indicatorul “Drum cu prioritate”. Autoturismul îi va acorda prioritate de dreapta autobuzului, deoarece autobuzul îi vine din partea dreaptă. Prin urmare, în această intersecțienuau prioritate de trecere autocamionul și autoturismul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1020.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1020.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1020; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție dirijată. Autobuzul(vine de jos) virează la stânga și are în față un indicator romboidal, cu fundal galben, ce semnifică drum cu prioritate, însoțit de același panou adițional. Autoturismul din stânga vrea să meargă înainte, având un indicator romboidal galben cu margini albe, cu panou adițional ce conține drumul ce începe din stânga și continuă în jos. Autocamionul vine din dreapta și vrea să meargă înainte, având un indicator triunghiular cu margini roșii și același panou adițional.","needsImageReview":true,"source":"RoDrive · ID 1019 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-cele-trei-vehicule-nu-au-prioritate-de-trecere","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1019","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1047.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1021","batch":"21","category":"Categoria B","question":"Persoanele accidentate, cu arsuri multiple pe corp și membre, trebuie să fie:","answers":["Dezbrăcate rapid de haine, după stingerea flăcărilor","Transportate urgent la o unitate medicală","Spălate, bandajate și apoi transportate la cea mai apropiată unitate sanitară"],"correctIndices":[1],"correct":1,"explanation":"Estecontraindicatca victimele cu arsuri multiple să fie dezbrăcate, se riscă să se smulgă pielea de pe acestea, hainele fiind lipite de piele și de răni. Acest lucru se va face doar de către personalul specializat. Persoanele accidentate, cu arsuri multiple pe corp și membre, trebuie să fie transportate urgent la o unitate medicală. Nu trebuie ca victimele cu arsuri multiple să fie spălate și bandajate, acest lucru se va face doar de către personalul specializat.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1021.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1021.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1021; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1020 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/persoanele-accidentate-cu-arsuri-multiple-pe-corp-si-membre-trebuie-sa-fie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1020","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1022","batch":"21","category":"Categoria B","question":"Care este limita legală de viteză în afara localităților, pe celelalte categorii de drumuri, altele decât autostrăzile, drumurile expres sau cele naționale europene (E)?","answers":["70 km/h","90 km/h","100 km/h"],"correctIndices":[1],"correct":1,"explanation":"Limita maximă de viteză pe drumurile din afara localităților este de 130 km/h pe autostrăzi, 120 km/h pe drumurile expres, 100 km/h pe drumurile naționale europene (E) și90 km/h pe celelalte categorii de drumuri. Aceste limite maxime de viteză sunt limitele maxime care se pot stabilii pe drumurile publice din România. Trebuie știut că, în funcție de categoria autovehiculului și de categoria drumului respectiv, limitele maxime de viteză sunt diferite. Aceste limite maxime de viteză de 130 km/h pe autostrăzi, 120 km/h pe drumurile expres, 100 km/h pe drumurile naționale europene (E) și90 km/h pe celelalte categorii de drumurisunt valabile pentru autovehiculele din categoriile A și B. Pentru limitele maxime de viteză pentru celelalte categorii de vehicule consultați Articolul 50 din OUG 195/2002, publicat mai jos.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1022.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1022.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1022; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1021 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-limita-legala-de-viteza-in-afara-localitatilor-pe-celelalte-categorii-de-drumuri-altele-decat-autostrazile-drumurile-expres-sau-ce","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1021","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1023","batch":"21","category":"Categoria B","question":"Ce se poate atașa unui autovehicul din categoria B?","answers":["O remorcă a cărei masă totală maximă autorizată să nu depășească 750 kg","O remorcă sau o semiremorcă, cu masa maximă autorizată de până la 1 t","O remorcă a cărei masă totală maximă autorizată depășește 750 kg, cu condiția ca masa totală maximă autorizată a ansamblului format din remorcă și un autovehicul trăgător din categoria b să nu depășească 4250 kg"],"correctIndices":[0,2],"correct":0,"explanation":"Unui autovehicul din categoria B i se poate atașa o remorcă ușoară, a cărei masă să nu depășească 750 kg sau o remorcă a cărei masă totală maximă autorizată depășește 750 kg, cu condiția ca masa totală maximă autorizată a ansamblului format din remorcă și un autovehicul trăgător din categoria B să nu depășească 4250 kg.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1023.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1023.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1023; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1022 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-se-poate-atasa-unui-autovehicul-din-categoria-b","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1022","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1024","batch":"21","category":"Categoria B","question":"Conducătorii de autovehicule pot folosi mijloace proprii de detectare a dispozitivelor de măsurare a vitezei?","answers":["Da","Nu","Acest aspect nu este stabilit legal"],"correctIndices":[0],"correct":0,"explanation":"Montarea sau folosirea dispozitivelor dedetectarea aparatelor radar este permisă, acestea se numescDETECTOARE-RADAR sauDETECTOARE-ANTIRADAR. Detectoarele radardoar detecteazăprezența aparatelor radar cu care se măsoară viteza și avertizează conducătorul auto despre existența unui astfel aparat radar în zonă, acestea fiind permise de lege. Legea interzice montarea sau folosirea dispozitivelorcare perturbă funcționarea normală a dispozitivelor radarcu care se măsoară vitezaAPARATE-ANTIRADAR. Acestea bruiază undele aparatului radar cu care se măsoară viteza și perturbă funcționarea acestora, de aceea sunt interzise, folosirea lor se consideră contravenție. Trebuie reținut căDETECTOARELE-RADAR sunt permise, iar APARATELE-ANTIRADARsunt interzise.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1024.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1024.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1024; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1023 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conducatorii-de-autovehicule-pot-folosi-mijloace-proprii-de-detectare-a-dispozitivelor-de-masurare-a-vitezei","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1023","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1025","batch":"21","category":"Categoria B","question":"Termenul de valabilitate a inspecției tehnice periodice poate fi regăsit:","answers":["Într-un document eliberat de service","În anexa certificatului de înmatriculare al autovehiculului","În manualul tehnic al autovehiculului sau al remorcii"],"correctIndices":[1],"correct":1,"explanation":"Termenul de valabilitate a inspecției tehnice periodice poate fi regăsit în anexa certificatului de înmatriculare al autovehiculului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1025.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1025.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1025; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1024 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/termenul-de-valabilitate-a-inspectiei-tehnice-periodice-poate-fi-regasit","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1024","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1026","batch":"21","category":"Categoria B","question":"Aprinderea luminii „martor“ de la bord, care semnalizează funcționarea generatorului de curent, poate indica:","answers":["Griparea rotorului pompei de apă","Ruperea curelei de antrenare a pompei de apă, a ventilatorului și a alternatorului","Scurgeri de electrolit din acumulatori"],"correctIndices":[1],"correct":1,"explanation":"Martorul de la bord semnalizează funcționarea defectuoasă a generatorului de curent, caz în care acesta nu mai produce curent. Generatorul de curent se mai numește și „alternator”. Alternatorul produce curent datorită unei mișcări de rotație care îi este transmisă de la motor prin intermediul unei curele. La modelele mai vechi de motoare această curea antrenează, pe lângă alternator, pompa de apă și ventilatorul de răcire al radiatorului. În cazul în care această curea se slăbește sau se rupe, toate cele trei nu mai primesc mișcare de rotație de la motor. La autovehiculele de generație nouă pompa de apă, ventilatorul și alternatorul nu mai sunt angrenate de aceeași curea. Pompa de apă poate fi acționată separat, prin intermediul unei curele dințate sau a unui lanț. Ventilatorul poate fi electric sau cu vasco-cuplu, iar alternatorul este pus pe o curea separată, iar dacă alternatorul nu mai funcționează, cel mai probabil, defecțiunea vine de la această curea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1026.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1026.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1026; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1025 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/aprinderea-luminii-martor-de-la-bord-care-semnalizeaza-functionarea-generatorului-de-curent-poate-indica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1025","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1027","batch":"21","category":"Categoria B","question":"Care dintre autovehicule va intra primul în intersecție?","answers":["Autocamionul, deoarece autoturismul virează la stânga și intersectează direcția acestuia de mers","Autoturismul, deoarece vine din dreapta autocamionului","Autocamionul, deoarece nu-și schimbă direcția de mers"],"correctIndices":[1],"correct":1,"explanation":"Intersecția este nedirijată, situație în care se va aplica regula priorității de dreapta. Autocamionul trebuie să îi acorde autoturismului prioritate de dreapta, deoarece autoturismul circulă din partea dreaptă a acestuia. Prin urmare, primul în această intersecție va intra autoturismul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1027.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1027.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1027; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție neridijată în care vehiculul roșu virează la stânga, iar cel albastru se deplasează înainte. Direcțiile lor de mers sunt intersectate. Autoturismul roșu vine din dreapta autocamionului.","needsImageReview":true,"source":"RoDrive · ID 1026 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-autovehicule-va-intra-primul-in-intersectie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1026","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/569.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1028","batch":"21","category":"Categoria B","question":"În care dintre situațiile de mai jos puteți folosi banda de lângă axa drumului pe o autostradă?","answers":["Când efectuați depășirea altor vehicule, dacă celelalte benzi în direcția de mers sunt ocupate","Când conduceți cu viteza maximă admisă","Când nu sunteți precedat de alte vehicule"],"correctIndices":[0],"correct":0,"explanation":"Când circulația se desfășoară pe un drum cu două sau mai multe benzi de circulație pe sens, ca de exemplu o autostradă cu trei benzi de circulație pe sensul de mers, aceste benzi se folosesc de către conducătorii de vehicule în funcție de intensitatea traficului și viteza de deplasare, aceștia având obligația să revină pe prima bandă ori de câte ori acest lucru este posibil. Prin urmare, atunci când efectuați depășirea altor vehicule pe autostradă, vă este permisă folosirea benzii de lângă axa drumului, dacă celelalte benzi în direcția de mers sunt ocupate. Atunci când conduceți pe o autostradă, puteți folosi banda de lângă axa drumuluidoar dacă celelalte benzi în sensul de mers sunt ocupate, și avețiobligația de a reveni pe prima bandă ori de câte ori acest lucru este posibil, această obligație fiind valabilăchiar și atunci când vă deplasați cu viteza maximă admisă. De exemplu, dacă traficul este liber pe o autostradă cu trei benzi de circulație pe sensul de mers, banda 1 sau 2 fiind neocupate, NU vă este permis să circulați pe banda de lângă axa drumului (banda 3), chiar dacă circulați cu viteză maximă admisă. Indiferent dacă sunteți sau nu precedat de alte vehicule, circulația pe benzi se va face ca în explicația de la varianta A de răspuns.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1028.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1028.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1028; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1027 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-situatiile-de-mai-jos-puteti-folosi-banda-de-langa-axa-drumului-pe-o-autostrada","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1027","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1029","batch":"21","category":"Categoria B","question":"Care este ordinea de trecere prin intersecție a autovehiculelor?","answers":["Autocamionul, autoturismul, motocicleta, troleibuzul","Troleibuzul, autocamionul, motocicleta, autoturismul","Autocamionul, autoturismul, troleibuzul, motocicleta"],"correctIndices":[2],"correct":2,"explanation":"Intersecția din imagine este dirijată cu indicatoare de reglementare de prioritate, sub fiecare indicator se găsește instalat câte un panou adițional care ne indică direcția drumului cu prioritate. Motocicleta și troleibuzul vin de pe drumurile fără prioritate, întâlnind indicatorul “Cedează trecerea” și au obligația să le acorde prioritate celorlalte autovehicule. Autocamionul și autoturismul vin de pe drumuri cu prioritate, ambele întâlnind indicatorul “Drum cu prioritate”, între acestea s-a creat o situație de egalitate, situație în care se va aplica regula priorității de dreapta, autoturismul îi va acorda prioritate de trecere autocamionului deoarece autocamionul îi vine din partea dreaptă. Ordinea de trecere este următoarea: autocamionul, autoturismul, troleibuzul iar ultima prin această intersecție va trece motocicleta.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1029.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1029.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1029; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă intersecție în care direcția drumului cu prioritate este spre dreapta, conform panourilor adiționale amplasate sub indicatoarele rutiere. Motocicleta vine de sus, și dorește să meargă înainte. În fața sa se află un indicator „Cedează trecerea” și un panou adițional care indică faptul că drumul cu prioritate este de jos, spre dreapta. Camionul albastru vine din dreapta, de pe drumul cu prioritate, și dorește să meargă înainte, având indicatorul galben de prioritate. Autoturismul roșu vine de jos și urmează să vireze la stânga. Este deja pe drumul cu prioritate, conform indicatorului galben.Tramvaiul verde vine din stânga, de pe un drum secundar, și dorește să meargă înainte. În fața lui se află un indicator „Cedează trecerea” și un panou adițional care indică faptul că trebuie să acorde prioritate celor de pe drumul cu prioritate, care vin din față și virează la stânga.","needsImageReview":true,"source":"RoDrive · ID 1028 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-ordinea-de-trecere-prin-intersectie-a-autovehiculelor","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1028","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1056.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1030","batch":"21","category":"Categoria B","question":"Într-o zonă rezidențială puteți circula cu:","answers":["Viteza minimă obligatorie de 20 km/h","Viteza maximă de 20 km/h","Viteza maximă de 30 km/h"],"correctIndices":[1],"correct":1,"explanation":"În zonele rezidențiale semnalizate ca atare aveți obligația să circulați cu o viteză de cel mult 20 de km/h și să nu staționați sau să parcați autovehiculul în afara spațiilor special destinate și semnalizate. Zona rezidențială este semnalizată la intrare cu indicatorul „Zonă rezidențială” iar la ieșire cu indicatorul „Sfârșitul zonei rezidențiale”.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1030.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1030.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1030; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1029 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intr-o-zona-rezidentiala-puteti-circula-cu","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1029","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1031","batch":"21","category":"Categoria B","question":"Oprirea voluntară este interzisă:","answers":["În intersecții","Pe drumurile cu prioritate","Pe sectoarele de drum neiluminate"],"correctIndices":[0],"correct":0,"explanation":"Se interzice oprirea voluntară a vehiculelor în intersecții, inclusiv în cele cu circulație în sens giratoriu, precum si în zona de preselecție unde sunt aplicate marcaje continue, iar în lipsa acestor marcaje, la o distanta mai mica de 25 de metri de colțul intersecției. Legislația rutieră nu prevede că pe drumurile cu prioritate se interzice oprirea voluntară a vehiculelor.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1031.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1031.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1031; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1030 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/oprirea-voluntara-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1030","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1032","batch":"21","category":"Categoria B","question":"În ce ordine vor trece prin intersecție autovehiculele?","answers":["Autoturismul, motocicleta, autobuzul","Motocicleta, autobuzul, autoturismul","Motocicleta, autoturismul, autobuzul"],"correctIndices":[2],"correct":2,"explanation":"Intersecția este dirijată prin indicatoare de reglementare de prioritate, pe drumul cu prioritate circulă motocicleta și autoturismul, acestea întâlnesc înaintea intersecției un indicator care le conferă prioritate de trecere, având prioritate de trecere față de autobuz care întâlnește indicatorul “Cedează trecerea”. Motocicleta și autoturismul vin de pe drumuri cu prioritate și au prioritate de trecere, însă autoturismul schimbând direcția de mers către stânga trebuie să îi acorde motocicletei prioritate de dreapta, deoarece motocicleta îi vine din partea dreaptă Prin urmare, ordinea de trecere este următoarea: prima va trece motocicleta, urmată de autoturism, iar ultimul prin această intersecție va trece autobuzul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1032.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1032.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1032; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Această intersecție este reglementată prin indicatoare triunghiulare cu margini roșii 'Cedează trecerea'. Motociclistul vine din stânga și merge înainte. Autoturismul vine din dreapta și virează la stânga. Autobuzul vine de sus și merge înainte, dar are indicatorul triunghiular cu margini roșii în față.","needsImageReview":true,"source":"RoDrive · ID 1031 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-ce-ordine-vor-trece-prin-intersectie-autovehiculele","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1031","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1060.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1033","batch":"21","category":"Categoria B","question":"Cum este sancționat conducătorul unui vehicul care a cumulat 15 puncte de penalizare?","answers":["Cu amendă contravențională","Cu suspendarea dreptului de a conduce pentru o perioadă de 30 de zile","Cu amendă contravențională și suspendarea exercitării dreptului de a conduce, pentru o perioadă de 60 de zile"],"correctIndices":[1],"correct":1,"explanation":"Atunci când titularul permisului de conducere a cumulat 15 puncte de penalizare se dispune măsura de reținere a permisului de conducere în vederea suspendării exercitării dreptului de a conduce pentru o perioadă de 30 de zile.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1033.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1033.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1033; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1032 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-este-sanctionat-conducatorul-unui-vehicul-care-a-cumulat-15-puncte-de-penalizare","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1032","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1034","batch":"21","category":"Categoria B","question":"În această situație trebuie să cedați trecerea vehiculului din dreapta?","answers":["Da, deoarece se aplică regula priorității de dreapta","Da, deoarece vă intersectați cu un drum prioritar","Nu, deoarece semaforul este pe culoarea verde"],"correctIndices":[2],"correct":2,"explanation":"Conducătorii de vehicule vor respecta semnificația semnalelor semafoarelor cu prioritate față de indicatoarele de reglementare de prioritate. În această intersecție veți respecta semnificația semnalului de culoare verde al semaforului care vă conferă prioritate de trecere. Prin urmare, în situația dată aveți prioritate față de autoturismul alb din dreapta.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1034.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1034.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1034; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată o intersecție din perspectiva unui șofer, semnalizată cu indicatorul 'STOP' și un semafor verde. De asemenea, există un indicator care interzice virajul la stânga. Un vehicul se află în dreapta și intenționează să meargă înainte. Șoferul inițial are semaforul verde.","needsImageReview":true,"source":"RoDrive · ID 1033 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-aceasta-situatie-trebuie-sa-cedati-trecerea-vehiculului-din-dreapta","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1033","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1062.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1035","batch":"21","category":"Categoria B","question":"Care dintre conducătorii autovehiculelor execută corect depășirea tramvaiului aflat în mers?","answers":["Ambii conducători","Conducătorul motocicletei","Conducătorul autoturismului"],"correctIndices":[0],"correct":0,"explanation":"Tramvaiele se depășesc,de regulă,pe partea dreaptă a acestora. Tramvaiele aflate în mers pot fi depășite și pe partea stângă atunci când drumul este cu sens unic sau când între șina din dreapta și marginea trotuarului nu există spațiu suficient pentru efectuarea manevrei. Motocicleta execută corect manevra de depășire a tramvaiului prin partea dreaptă, conform cu regula generală pentru depășirea tramvaielor, detaliată mai sus. Autoturismul roșu execută corect manevra de depășire a tramvaiului prin partea stângă, conform cu excepția de la regula generală care spune că tramvaieleaflate în merspot fi depășite și pe partea stângă atunci când între șina din dreapta și marginea trotuarului nu există spațiu suficient, excepție detaliată mai sus. Presupunând că intersecția este dirijată și depășirea vehiculelor este permisă, ambii conducători ai autovehiculelor execută corect manevra de depășire a tramvaiului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1035.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1035.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1035; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un autoturism roșu care depășește un tramvai pe stânga, în timp ce tramvaiul circulă, la dreapta sa, pe șine și un motociclist circulă la dreapta amândurora. Toți merg înainte. Mașina depășește pe stânga, aflându-se în continuare pe sensul de mers, neavând loc pentru a putea depăși pe dreapta.","needsImageReview":true,"source":"RoDrive · ID 1034 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-conducatorii-autovehiculelor-executa-corect-depasirea-tramvaiului-aflat-in-mers","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1034","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1063.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1036","batch":"21","category":"Categoria B","question":"În care dintre situații se reține certificatul de înmatriculare sau înregistrare?","answers":["Când inspecția tehnică periodică a expirat","Când claxonul nu funcționează la parametri optimi","Când motorul emite diverse zgomote"],"correctIndices":[0],"correct":0,"explanation":"Certificatul de înmatriculare sau de înregistrare ori dovada înlocuitoare a acestuia se reține de către poliția rutieră atunci când: Nu se aplică reținerea certificatului de înmatriculare sau înregistrare ori alte sancțiuni atunci când claxonul nu funcționează la parametri optimi. Nu se aplică reținerea certificatului de înmatriculare sau înregistrare ori alte sancțiuni atunci când motorul emite diverse zgomote, atât timp cât acele zgomote nu depășesc limita legal admisă pentru tipul respectiv de vehicul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1036.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1036.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1036; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1035 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-situatii-se-retine-certificatul-de-inmatriculare-sau-inregistrare","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1035","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1037","batch":"21","category":"Categoria B","question":"Ce interdicție au conducătorii de vehicule atunci când circulă pe drumuri acoperite de zăpadă, gheață sau polei?","answers":["De a circula pe sectoarele respective de drum fără autorizație de la administrația drumurilor","De a circula cu un autovehicul a cărui masă totală maximă este mai mare de 3,5 tone, fără a avea montate pe roți lanțuri sau alte echipamente antiderapante omologate","De a efectua depășiri"],"correctIndices":[1],"correct":1,"explanation":"Nu este obligatorie obținerea unei autorizații pentru a circulă pe sectoarele de drum acoperite de zăpadă, gheață sau polei. Conducătorului de autovehicul îi este interzis să circule cu autovehiculul cu masa totala maximă autorizatămai mare de 3,5 tonepe drumurile acoperite cu zăpadă, gheață sau polei,fără a avea montate pe roți lanțuri sau alte echipamente antiderapante omologate, în perioadele și pe drumurile stabilite prin ordin al ministrului transporturilor, construcțiilor si turismului. Aceste zone sunt semnalizate, în general, cu indicatorul „Lanțuri pentru zăpadă”. Legislația rutieră sancționează conducerea autovehiculului cu o masă totală maximă autorizatămai mare de 3,5 tonepe drumurile publice acoperite cu zăpadă, gheață sau polei, fără anvelope de iarnă pe roțile axei/axelor de tracțiune, sau lanțuri ori alte echipamente antiderapante certificate montate pe roțile axei/axelor de tracțiune.Este important să reținem că acest articol de lege lasă,la alegere, două variante:fie anvelope de iarnă pe roțile axei/axelor de tracțiune,fie lanțuri ori alte echipamente antiderapante certificate aplicate pe anvelopele de vară de pe roțile axei/axelor de tracțiune.Însă indicatorul „Lanțuri pentru zăpadă” nu lasă opțiunea de a alege una dintre aceste două opțiuni, ci obligă la dotarea cu lanțuri pentru zăpadă, indiferent dacă anvelopele sunt de vară sau de iarnă. Nu se interzice manevra de depășire atunci când se circulă pe sectoarele de drum acoperite de zăpadă, gheață sau polei, dar se recomandă să se efectueze cu viteză redusă, cu prudență sporită și să se respecte limita m","imageUrl":"/nivel-1/quiz-images/rodrive-all/1037.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1037.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1037; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1036 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-interdictie-au-conducatorii-de-vehicule-atunci-cand-circula-pe-drumuri-acoperite-de-zapada-gheata-sau-polei","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1036","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1038","batch":"21","category":"Categoria B","question":"Pentru care dintre situațiile de mai jos se dispune reținerea permisului de conducere?","answers":["Pentru nerespectarea normelor legale referitoare la verificarea medicală periodică","Pentru acumularea a 10 puncte de penalizare","Când permisul de conducere prezintă modificări, ștersături sau adăugiri"],"correctIndices":[2],"correct":2,"explanation":"Legislația rutieră nu prevede măsura de reținere a permisului de conducere pentru nerespectarea normelor legale referitoare la verificarea medicală periodică și nici nu impune o astfel de obligație pentru conducătorul de autovehicul, tractor agricol sau forestier ori tramvai. Prin urmare, varianta A de răspuns nu poate fi corectă. Legislația rutieră prevede că în cazul cumulării punctelor de penalizare, suspendarea exercitării dreptului de a conduce se va dispune pentru o perioadă de 30 de zilela cumularea a15puncte de penalizare, nu la acumularea a10puncte de penalizare așa cum este specificat în această variantă de răspuns. Având în vedere că la acumularea a 10 puncte de penalizareNUse suspendă exercitarea dreptului de a conduce,NUse aplică nici măsura de reținere a permisului de conducere în vederea suspendării exercitării dreptului de a conduce. Prin urmare, varianta B de răspuns nu poate fi corectă. Atunci când permisul de conducere este deteriorat, prezintă modificări, ștersături sau adăugiri, se dispune măsura de reținere a acestuia de către polițistul rutier.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1038.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1038.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1038; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1037 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pentru-care-dintre-situatiile-de-mai-jos-se-dispune-retinerea-permisului-de-conducere","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1037","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1039","batch":"21","category":"Categoria B","question":"Ce obligații are conducătorul auto atunci când un polițist îi solicită documentele?","answers":["Să prezinte certificatul de înmatriculare și cartea de identitate a vehiculului","Să prezinte documentele personale","Să înmâneze documentele prevăzute de lege"],"correctIndices":[2],"correct":2,"explanation":"Această variantă nu este corectă deoarece conține „cartea de identitate a vehiculului”, document care, conform legislației rutiere, nu este prevăzut printre documentele pe care le solicită polițistul. Această variantă nu este corectă deoarece „documentele personale” pot fi: card, pașaport, bilet de avion, etc.. Participanții la trafic sunt obligați ca, la cererea polițistului rutier, să înmâneze acestuia documentul de identitate sau, după caz, permisul de conducere, documentul de înmatriculare sau de înregistrare a vehiculului condus, documentele referitoare la bunurile transportate, precum și alte documente prevăzute de lege.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1039.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1039.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1039; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1038 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-are-conducatorul-auto-atunci-cand-un-politist-ii-solicita-documentele","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1038","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1040","batch":"21","category":"Categoria B","question":"Cum trebuie să procedeze conducătorul unui vehicul dacă în timpul deplasării apar probleme tehnice care fac imposibilă continuarea călătoriei?","answers":["Dacă nu poate înlătura defecțiunile, să se deplaseze la cea mai apropiată unitate de depanare","Să scoată vehiculul în afara părții carosabile","Să asigure vehiculul contra efracției și să plece după ajutor"],"correctIndices":[1],"correct":1,"explanation":"Dacă în timpul deplasării cu vehiculul apar probleme tehnice care fac imposibilă continuarea călătoriei, aveți obligația de a scoate vehiculul în afara părții carosabile sau, dacă nu este posibil, de a-l deplasa cât mai aproape de bordură sau acostament, așezându-l paralel cu axa drumului, semnalizându-i prezența prin punerea în funcțiune a luminilor de avarie și prin instalarea triunghiurilor reflectorizante, luând măsuri pentru remedierea deficiențelor sau, după caz, de remorcare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1040.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1040.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1040; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1039 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-procedeze-conducatorul-unui-vehicul-daca-in-timpul-deplasarii-apar-probleme-tehnice-care-fac-imposibila-continuarea-calatorie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1039","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1041","batch":"21","category":"Categoria B","question":"Este permisă depășirea când din sens opus se apropie un alt vehicul?","answers":["Da, dacă cel care se apropie din sens opus a redus viteza de deplasare pentru a facilita depășirea","Nu, dacă cel care se apropie din sens opus este obligat să efectueze manevre de evitare a coliziunii","Da, dacă spațiul lateral este suficient"],"correctIndices":[1],"correct":1,"explanation":"Conducătorii vehiculelor care circulă din sens opusnu au obligațiade a reduce viteza sau de a vă facilita în vreun fel manevra de depășire pe care o efectuați. De aceea, chiar dacă conducătorul vehiculului care circulă din sens opus are intenții bune și încearcă să faciliteze manevra,nu vă puteți baza doar pe atât. Trebuie să respectați prevederile legale privind manevra de depășire (vedeți explicația de la varianta B de răspuns pentru mai multe detalii). Vă este interzisă manevra de depășire atunci când din sens opus se apropie un alt vehicul, iar conducătorul acestuiaeste obligat să efectueze manevre de evitare a coliziunii. Aceste situații se creează atunci când pentru manevra de depășire este necesară intrarea pe sensul opus de circulație. Dacă pe sensul dvs. de mers există spațiu suficient astfel încât pentru efectuarea manevreinu se intră pe sensul opus de circulație, vehiculul din sens opusnu este obligatsă efectueze manevre de evitare a coliziunii, iar manevra de depășire este permisă. Chiar dacă cel care depășește consideră ca spațiul lateral este suficient, este posibil ca cel ce conduce vehiculul care vine din sens opus să nu considere la fel sau să se afle poziționat spre axul drumului și să fie nevoit să efectueze manevre de evitare a coliziunii, caz în care manevra de depășire este interzisă. Spațiul lateral suficient nu este singura condiție pentru ca depășirea să se poată efectua. Depășirea este permisă când se întrunesc toate condițiile pentru ca manevra sa fie regulamentară și să se poată efectua în condiții de siguranță pentru toți participanții la trafic","imageUrl":"/nivel-1/quiz-images/rodrive-all/1041.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1041.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1041; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1040 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-permisa-depasirea-cand-din-sens-opus-se-apropie-un-alt-vehicul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1040","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1042","batch":"21","category":"Categoria B","question":"Este permisă remorcarea unui autovehicul pe autostradă?","answers":["Nu, legea interzice în mod expres acest lucru","Da, dacă ansamblul astfel format poate depăși viteza de 50 km/h","Da, dacă autovehiculul remorcat este un autoturism"],"correctIndices":[1],"correct":1,"explanation":"Pe autostradă este permisă remorcarea unui autovehicul, cu condiția ca ansamblul rezultat să fie capabil să depășească viteza de 50 de km/h. Prin urmare, dacă ansamblul poate atinge o viteză mai mare de 50 de km/h, circulația îi este permisă, în timp ce, în cazul în care acesta nu poate atinge această viteză de 50 de km/h, circulația îi este interzisă. Este important să rețineți că, pe lângă permisiunea de a remorca un alt autovehicul, trebuie să respectați și toate regulile prevăzute de legislația rutieră în ceea ce privește remorcarea autovehiculelor.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1042.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1042.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1042; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1041 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-permisa-remorcarea-unui-autovehicul-pe-autostrada","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1041","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1043","batch":"21","category":"Categoria B","question":"Este regulamentar să depășiți autobuzul oprit în stație?","answers":["Da, dacă vă asigurați și semnalizați","Da, numai dacă autobuzul are refugiu pentru pietoni","Nu, până la plecarea autobuzului din stație"],"correctIndices":[0],"correct":0,"explanation":"În situația în care întâlniți un autobuz oprit într-o stație vă este permis să efectuați manevra de depășire a acestuia, însă trebuie să vă asigurați, să semnalizați intenția și să respectați toate regulile privind efectuarea manevrei de depășire. Din punct de vedere al conduitei preventive se recomandă să sporiți atenția deoarece unii pietoni pot traversa strada prin fața autobuzului fără să se asigure. Variantele de răspuns B și C ar fi fost corecte în cazul în care era vorba despre untramvai, însă în acest caz este vorba despre unautobuz.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1043.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1043.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1043; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o situație de trafic urban cu un autobuz staționat pe banda din dreapta, în stație. Șoferul autoturismului intenționează să depășească.","needsImageReview":true,"source":"RoDrive · ID 1042 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-regulamentar-sa-depasiti-autobuzul-oprit-in-statie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1042","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1071.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1044","batch":"21","category":"Categoria B","question":"Ce se întâmplă atunci când, pe roțile unei osii, eficiența frânării este mult diferită?","answers":["Se reduce viteza de deplasare","Vehiculul își menține ținuta de drum, în ciuda acestui fapt","Vehiculul poate derapa lateral"],"correctIndices":[2],"correct":2,"explanation":"Atât timp cât nu se frânează nu se reduce viteza de deplasare, chiar dacă pe roțile unei osii, eficiența frânării este mult diferită. Consecințele sunt cele de la varianta C de răspuns. Atunci când pe roțile unei osii eficiența frânării este mult diferită, frânarea se va face mai puternic pe o parte a vehiculului și poate derapa lateral.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1044.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1044.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1044; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1043 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-se-intampla-atunci-cand-pe-rotile-unei-osii-eficienta-franarii-este-mult-diferita","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1043","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1045","batch":"21","category":"Categoria B","question":"Cum se sancționează neacordarea priorității de către conducătorii de autovehicule / tractoare agricole sau forestiere pietonilor angajați în traversarea drumurilor publice, atunci când au acest drept?","answers":["Prin anularea permisului de conducere","Prin amendă contravențională și suspendarea exercitării dreptului de a conduce autovehicule","Prin amendă contravențională și puncte de penalizare"],"correctIndices":[1],"correct":1,"explanation":"Conducătorul de vehicul este obligat să acorde prioritate de trecere pietonului care traversează drumul public, prin loc special amenajat, marcat și semnalizat corespunzător ori la culoarea verde a semaforului destinat lui, atunci când acesta se află pe sensul de mers al vehiculului. Nerespectarea acestei obligații se consideră contravenție și se sancționează cu amenda contravențională prevăzută în clasa a III-a de sancțiuni și cu aplicarea măsurii de reținere a permisului de conducere în vederea suspendării dreptului de a conduce pentru o perioadă de 60 de zile.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1045.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1045.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1045; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1044 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-se-sanctioneaza-neacordarea-prioritatii-de-catre-conducatorii-de-autovehicule-tractoare-agricole-sau-forestiere-pietonilor-angajati-in-t","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1044","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1046","batch":"21","category":"Categoria B","question":"Cum trebuie să procedați în situația dată, dacă semnalele luminoase și sonore nu funcționează?","answers":["Opriți fără a depăși calea ferată, vă asigurați și vă continuați deplasarea, dacă nu se apropie trenul","Reduceți viteza și vă continuați deplasarea, după ce vă asigurați că nu se apropie trenul","Opriți numai dacă se apropie trenul"],"correctIndices":[0],"correct":0,"explanation":"În situația dată, dacă semnalele luminoase și sonore nu funcționează, trecerea devine o trecere la nivel cu o cale ferată fără bariere și fără semnalizare luminoasă automată, caz în care aveți obligația de a opri fără a depăși locul unde este instalat indicatorul, vă asigurați că din partea stângă sau din partea dreaptă nu se apropie un vehicul feroviar, după care vă puteți continua deplasarea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1046.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1046.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1046; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere la nivel cu calea ferată semnalizată prin indicatorul 'Crucea Sfântului Andrei' și lumini intermitente, ceea ce arată o trecere pe cale ferată fără bariere. Luminile, însă, nu funcționează","needsImageReview":true,"source":"RoDrive · ID 1045 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-procedati-in-situatia-data-daca-semnalele-luminoase-si-sonore-nu-functioneaza","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"1045","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_1074.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1047","batch":"21","category":"Categoria B","question":"Punctele de penalizare se aplică:","answers":["Pentru pătrunderea într-o intersecție atunci când circulația este blocată în interiorul acesteia","Pentru lăsarea liberă a volanului în timpul conducerii","Pentru aruncarea de obiecte pe drumul public"],"correctIndices":[0],"correct":0,"explanation":"Vă este interzisă pătrunderea într-o intersecție atunci când circulația în interiorul acesteia este blocată, indiferent daca va deplasați sau nu pe drumul cu prioritate. În acest caz trebuie să așteptați deblocarea intersecției și doar după deblocarea acesteia puteți pătrunde în intersecție. Pentru pătrunderea într-o intersecție atunci când circulația în interiorul acesteia este blocată se aplică amenda contravențională prevăzută în clasa a II-a de sancțiuni și 3 puncte de penalizare. Pentru lăsarea liberă a volanului în timpul conducerii nu se aplică puncte de penalizare. Pentru această faptă se aplică amenda prevăzută în clasa I de sancțiuni. Pentru aruncarea de obiecte pe drumul public nu se aplică puncte de penalizare. Pentru această faptă se aplică amenda prevăzută în clasa a IV-a de sancțiuni.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1047.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1047.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1047; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1046 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/punctele-de-penalizare-se-aplica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1046","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1048","batch":"21","category":"Categoria B","question":"Printre primele cauze ale accidentelor rutiere figurează și neatenția în conducere. Cum poate fi evitată aceasta?","answers":["Prin alternarea stării de vigilență cu cea de relaxare la volan, îndeosebi pe sectoarele de drum în aliniament","Prin concentrarea permanentă doar asupra activităților pe care trebuie să le efectuați pentru conducerea autovehiculului în condiții de siguranță","Prin punerea în funcțiune a unor surse de muzică cu intensitate sonoră mare, pentru stimularea vigilenței în conducere"],"correctIndices":[1],"correct":1,"explanation":"Este recomandat să ai o stare de relaxare în schimbul stării de încordare continuă, dar în tot acest timp de conducere, fie că abordați o stare de relaxare sau de încordare, trebuie să păstrați vigilența la cel mai înalt nivel. Prin urmare, nu puteți alterna între starea de relaxare și starea de vigilență,deoarece vigilența trebuie să fie continuă. Neatenția în conducere, care se numără printre principalele cauze de producere a accidentelor rutiere, poate fi evitată dacă vă concentrați permanent doar asupra activităților pe care trebuie să le efectuați pentru conducerea autovehiculului în condiții de siguranță. În general, muzica induce o stare de relaxare, dar în același timp distrage atenția, puterea de concentrare și vigilența, mai ales când este ascultată la o intensitate mare. Trebuie știut că legislația rutieră interzice folosirea sistemelor de sonorizare ale autovehiculelor la o intensitate care ar afecta deplasarea în siguranță a lui și a celorlalți participanți la trafic.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1048.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1048.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1048; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1047 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/printre-primele-cauze-ale-accidentelor-rutiere-figureaza-si-neatentia-in-conducere-cum-poate-fi-evitata-aceasta","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1047","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1049","batch":"21","category":"Categoria B","question":"Ce rând trebuie să ocupe conducătorul de vehicul și de la ce distanță, pentru a se deplasa pe direcția înainte, într-o intersecție fără marcaje din afara localității?","answers":["Rândul din stânga, de la o distanță de cel puțin 100 m","Rândul din stânga sau din dreapta, de la o distanță de cel puțin 50 m","Rândul din dreapta, de la o distanță de cel puțin 100 m"],"correctIndices":[1],"correct":1,"explanation":"La intersecțiile fără marcaje de delimitare a benzilor, conducătorii vehiculelor ocupa în mers,cu cel puțin 50 m înainte de intersecție, următoarele poziții:","imageUrl":"/nivel-1/quiz-images/rodrive-all/1049.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1049.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1049; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1048 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-rand-trebuie-sa-ocupe-conducatorul-de-vehicul-si-de-la-ce-distanta-pentru-a-se-deplasa-pe-directia-inainte-intr-o-intersectie-fara-marcaj","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1048","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-1050","batch":"21","category":"Categoria B","question":"Cum procedați când urmează să traversați o trecere la nivel cu calea ferată simplă, fără bariere?","answers":["Opriți, fără a depăși indicatorul în cruce, vă angajați și traversați numai după ce v-ați asigurat că nu există niciun pericol","Reduceți viteza, vă asigurați în stânga și în dreapta, după care traversați cu atenție","Opriți sau, dacă nu e cazul, doar reduceți viteza, vă asigurați, traversați calea ferată, după care vă continuați drumul"],"correctIndices":[0],"correct":0,"explanation":"Atunci când urmează să traversați o trecere la nivel cu o calea ferată simplă sau dublă, fără bariere, aveți obligația de a opri în locul cu vizibilitate maximă asupra căii ferate dar fără a depăși indicatoarele, vă asigurați că din partea stângă sau din partea dreaptă nu se apropie un vehicul feroviar, după care vă continuați deplasarea. Obligațiile enumerate la aceste variante de răspuns (B și C) le aveți la trecerile la nivel cu o cale ferată prevăzută cu bariere sau semibariere, în cazul în care acestea sunt ridicate iar semnalul cu lumină albă cu cadență lentă este în funcțiune.","imageUrl":"/nivel-1/quiz-images/rodrive-all/1050.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/1050.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 1050; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 1049 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-cand-urmeaza-sa-traversati-o-trecere-la-nivel-cu-calea-ferata-simpla-fara-bariere","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"1049","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}]);})();
